wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(29994937688529439)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>unistr('\52A0\8F7D\5F53\524D KBot \8FDE\63A5')
,p_static_id=>'load-connection'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_has_key       VARCHAR2(1);',
'    l_config_status VARCHAR2(64);',
'BEGIN',
'    SELECT rawtohex(config_id),',
'           protocol,',
'           host,',
'           port,',
'           CASE WHEN web_credential IS NOT NULL THEN ''Y'' ELSE ''N'' END,',
'           status',
'      INTO :P1_CONFIG_ID,',
'           :P1_PROTOCOL,',
'           :P1_HOST,',
'           :P1_PORT,',
'           l_has_key,',
'           l_config_status',
'      FROM kbot_apex_platform_config',
'     WHERE type_1 = ''KBOT_SERVICE''',
'       AND type_2 = ''SERVICE'';',
'',
'    :P1_CURRENT_STATUS := CASE',
unistr('        WHEN l_config_status = ''ACTIVE'' THEN ''\5DF2\914D\7F6E\5E76\542F\7528'''),
unistr('        ELSE ''\914D\7F6E\5DF2\505C\7528'''),
'    END;',
'    :P1_STATUS_LEVEL := CASE',
'        WHEN l_config_status = ''ACTIVE'' THEN ''configured''',
'        ELSE ''disabled''',
'    END;',
'    :P1_CREDENTIAL_STATUS := CASE',
unistr('        WHEN l_has_key = ''Y'' THEN ''\5DF2\914D\7F6E\FF08\5B89\5168\9690\85CF\FF09'''),
unistr('        ELSE ''\672A\914D\7F6E'''),
'    END;',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        :P1_CONFIG_ID := NULL;',
'        :P1_PROTOCOL := NULL;',
'        :P1_HOST := NULL;',
'        :P1_PORT := NULL;',
unistr('        :P1_CURRENT_STATUS := ''\5C1A\672A\914D\7F6E'';'),
'        :P1_STATUS_LEVEL := ''missing'';',
unistr('        :P1_CREDENTIAL_STATUS := ''\672A\914D\7F6E'';'),
'END;',
'',
':P1_EFFECTIVE_URL := CASE',
'    WHEN :P1_PROTOCOL IS NOT NULL AND :P1_HOST IS NOT NULL THEN',
'        :P1_PROTOCOL || ''://'' || :P1_HOST ||',
'        CASE WHEN :P1_PORT IS NOT NULL THEN '':'' || :P1_PORT END',
'    ELSE regexp_replace(',
'        rtrim(apex_util.host_url(''HOST''), ''/''),',
'        '':(8080|8181)$'',',
'        ''''',
'    )',
'END;',
':P1_WEB_CREDENTIAL := NULL;',
':P1_CLEAR_CREDENTIAL := NULL;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>29994937688529439
);
