,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_protocol       VARCHAR2(32) := lower(trim(:P1_PROTOCOL));',
'    l_host           VARCHAR2(1020) := trim(:P1_HOST);',
'    l_port           NUMBER := :P1_PORT;',
'    l_base_url       VARCHAR2(4000);',
'    l_existing_key   VARCHAR2(4000);',
'    l_effective_key  VARCHAR2(4000);',
'    l_response       CLOB;',
'    l_ready_status   VARCHAR2(64);',
'    l_error_message  VARCHAR2(4000);',
'BEGIN',
'    IF l_protocol IS NULL AND l_host IS NULL THEN',
'        IF l_port IS NOT NULL THEN',
unistr('            raise_application_error(-20001, ''\76F8\5BF9\5730\5740\6A21\5F0F\4E0D\80FD\5355\72EC\586B\5199\7AEF\53E3\3002'');'),
'        END IF;',
'        l_base_url := regexp_replace(',
'            rtrim(apex_util.host_url(''HOST''), ''/''),',
'            '':(8080|8181)$'',',
'            ''''',
'        );',
'    ELSIF l_protocol IS NULL OR l_host IS NULL THEN',
unistr('        raise_application_error(-20001, ''\72EC\7ACB\670D\52A1\6A21\5F0F\5FC5\987B\540C\65F6\586B\5199\534F\8BAE\548C Host\3002'');'),
'    ELSE',
'        IF l_protocol NOT IN (''http'', ''https'') THEN',
unistr('            raise_application_error(-20001, ''\534F\8BAE\53EA\80FD\9009\62E9 HTTP \6216 HTTPS\3002'');'),
'        END IF;',
'        IF instr(l_host, ''://'') > 0',
'           OR regexp_like(l_host, ''[[:space:]/?#]'') THEN',
unistr('            raise_application_error(-20001, ''Host \53EA\80FD\586B\5199\4E3B\673A\540D\6216 IP\FF0C\4E0D\80FD\5305\542B\534F\8BAE\3001\8DEF\5F84\3001\53C2\6570\6216\7A7A\683C\3002'');'),
'        END IF;',
'        IF l_port IS NOT NULL',
'           AND (l_port < 1 OR l_port > 65535 OR l_port <> trunc(l_port)) THEN',
unistr('            raise_application_error(-20001, ''\7AEF\53E3\5FC5\987B\662F 1 \81F3 65535 \7684\6574\6570\3002'');'),
'        END IF;',
'        l_base_url := l_protocol || ''://'' || l_host ||',
'            CASE WHEN l_port IS NOT NULL THEN '':'' || to_char(l_port) END;',
'    END IF;',
'',
'    BEGIN',
'        SELECT web_credential',
'          INTO l_existing_key',
'          FROM kbot_apex_platform_config',
'         WHERE type_1 = ''KBOT_SERVICE''',
'           AND type_2 = ''SERVICE'';',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN',
'            l_existing_key := NULL;',
'    END;',
'',
'    l_effective_key := CASE',
'        WHEN :P1_CLEAR_CREDENTIAL = ''Y'' THEN NULL',
'        WHEN :P1_WEB_CREDENTIAL IS NOT NULL THEN :P1_WEB_CREDENTIAL',
'        ELSE l_existing_key',
'    END;',
'',
'    apex_web_service.g_request_headers.delete;',
'    apex_web_service.g_request_headers(1).name := ''Accept'';',
'    apex_web_service.g_request_headers(1).value := ''application/json'';',
'    apex_web_service.g_request_headers(2).name := ''X-Request-ID'';',
'    apex_web_service.g_request_headers(2).value := lower(rawtohex(sys_guid()));',
'    IF l_effective_key IS NOT NULL THEN',
'        apex_web_service.g_request_headers(3).name := ''Authorization'';',
'        apex_web_service.g_request_headers(3).value := ''Bearer '' || l_effective_key;',
'    END IF;',
'',
'    BEGIN',
'        l_response := apex_web_service.make_rest_request(',
'            p_url         => rtrim(l_base_url, ''/'') || ''/readyz'',',
'            p_http_method => ''GET''',
'        );',
'    EXCEPTION',
'        WHEN OTHERS THEN',
'            l_error_message := substr(SQLERRM, 1, 3000);',
'            raise_application_error(',
'                -20002,',
unistr('                ''\65E0\6CD5\8FDE\63A5 KBot Main API\FF1A'' || l_error_message'),
'            );',
'    END;',
'',
'    IF apex_web_service.g_status_code <> 200 THEN',
'        raise_application_error(',
'            -20002,',
unistr('            ''KBot Main API \5065\5EB7\68C0\67E5\5931\8D25\FF0CHTTP \72B6\6001\7801\FF1A'' ||'),
'            apex_web_service.g_status_code',
'        );',
'    END IF;',
'',
'    l_ready_status := lower(json_value(l_response, ''$.status''));',
'    IF nvl(l_ready_status, ''unknown'') <> ''ready'' THEN',
'        raise_application_error(',
'            -20002,',
unistr('            ''KBot Main API \5C1A\672A\5C31\7EEA\FF1A'' ||'),
unistr('            coalesce(json_value(l_response, ''$.message''), l_ready_status, ''\672A\77E5\72B6\6001'')'),
'        );',
'    END IF;',
'',
'    IF :REQUEST = ''SAVE-CONNECTION'' THEN',
'        MERGE INTO kbot_apex_platform_config target',
'        USING (',
'            SELECT ''KBOT_SERVICE'' AS type_1,',
'                   ''SERVICE'' AS type_2',
'              FROM dual',
'        ) source',
'           ON (target.type_1 = source.type_1 AND target.type_2 = source.type_2)',
'        WHEN MATCHED THEN',
'            UPDATE SET target.protocol = l_protocol,',
'                       target.host = l_host,',
'                       target.port = l_port,',
'                       target.status = ''ACTIVE'',',
'                       target.web_credential = l_effective_key,',
'                       target.updated_by = :APP_USER,',
'                       target.updated_at = systimestamp',
'        WHEN NOT MATCHED THEN',
'            INSERT (',
'                config_id,',
'                type_1,',
'                type_2,',
'                protocol,',
'                host,',
'                port,',
'                status,',
'                web_credential,',
'                created_by,',
'                updated_by,',
'                created_at,',
'                updated_at',
'            ) VALUES (',
'                sys_guid(),',
'                source.type_1,',
'                source.type_2,',
'                l_protocol,',
'                l_host,',
'                l_port,',
'                ''ACTIVE'',',
'                l_effective_key,',
'                :APP_USER,',
'                :APP_USER,',
'                systimestamp,',
'                systimestamp',
'            );',
'',
unistr('        :P1_CURRENT_STATUS := ''\8FDE\63A5\6B63\5E38\FF0C\914D\7F6E\5DF2\4FDD\5B58'';'),
'        :P1_STATUS_LEVEL := ''ready'';',
'        :P1_CREDENTIAL_STATUS := CASE',
unistr('            WHEN l_effective_key IS NOT NULL THEN ''\5DF2\914D\7F6E\FF08\5B89\5168\9690\85CF\FF09'''),
unistr('            ELSE ''\672A\914D\7F6E'''),
'        END;',
'        apex_application.g_print_success_message :=',
unistr('            ''\8FDE\63A5\6D4B\8BD5\901A\8FC7\FF0CKBot Main API \914D\7F6E\5DF2\4FDD\5B58\3002'';'),
'    ELSE',
unistr('        :P1_CURRENT_STATUS := ''\8FDE\63A5\6D4B\8BD5\901A\8FC7'';'),
'        :P1_STATUS_LEVEL := ''ready'';',
'        :P1_CREDENTIAL_STATUS := CASE',
unistr('            WHEN l_effective_key IS NOT NULL THEN ''\5DF2\914D\7F6E\FF08\5B89\5168\9690\85CF\FF09'''),
unistr('            ELSE ''\672A\914D\7F6E'''),
'        END;',
'        apex_application.g_print_success_message :=',
unistr('            ''\8FDE\63A5\6D4B\8BD5\901A\8FC7\FF0CKBot Main API \5DF2\5C31\7EEA\FF1B\5C1A\672A\4FDD\5B58\672C\6B21\4FEE\6539\3002'';'),
'    END IF;',
'',
'    :P1_EFFECTIVE_URL := l_base_url;',
'    :P1_PROTOCOL := l_protocol;',
'    :P1_HOST := l_host;',
'    :P1_WEB_CREDENTIAL := NULL;',
'    :P1_CLEAR_CREDENTIAL := NULL;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'TEST-CONNECTION,SAVE-CONNECTION'
,p_process_when_type=>'REQUEST_IN_CONDITION'
,p_internal_uid=>29995038198529439
);
end;
